def agent_action(sandbox, agent_body, step_count):
    seat = sandbox.get_swing_seat()
    if seat is None:
        return

    pos = seat.position
    vel = seat.linearVelocity
    vx = vel.x
    vy = vel.y
    target_y = 11.7
    target_x_min, target_x_max = 9.35, 10.65
    dead_zone_threshold = 0.5  # Minimum speed to apply forces
    wind_compensation = 0.5  # Tuned to counteract wind

    # Check if in target zone
    if pos.y >= target_y and target_x_min <= pos.x <= target_x_max:
        # At apex or falling into zone
        if abs(vx) < 1.0 and abs(vy) < 1.0:
            # At apex, stop
            sandbox.apply_force_to_seat(0, 0)
        else:
            # Falling into zone, apply small upward impulse
            if vy < 0:
                sandbox.apply_impulse_to_seat(0, 4.2)
            else:
                sandbox.apply_impulse_to_seat(0, -4.2)
        return

    # Horizontal control: counteract wind and guide to target x range
    if abs(vx) < dead_zone_threshold:
        # Apply impulse to increase horizontal speed
        if pos.x < target_x_min:
            sandbox.apply_impulse_to_seat(4.2, 0)  # Rightward impulse
        elif pos.x > target_x_max:
            sandbox.apply_impulse_to_seat(-4.2, 0)  # Leftward impulse
    else:
        horizontal_force = 0
        if pos.x < target_x_min:
            horizontal_force += 42.0  # Rightward force
        elif pos.x > target_x_max:
            horizontal_force -= 42.0  # Leftward force
        # Adjust for wind by applying a force opposite to current horizontal velocity
        horizontal_force -= vx * wind_compensation
        sandbox.apply_force_to_seat(horizontal_force, 0)

    # Vertical control: increase height if below target y
    if pos.y < target_y:
        # Apply upward force
        sandbox.apply_force_to_seat(0, 42.0)
    else:
        # If above target y and not in x range, adjust vertical trajectory
        if pos.x < target_x_min or pos.x > target_x_max:
            if vy > 0:  # Rising, apply downward force
                sandbox.apply_force_to_seat(0, -42.0)
            else:  # Falling, apply upward force
                sandbox.apply_force_to_seat(0, 42.0)
        else:
            # In x range but not in target y, adjust vertical
            if abs(vy) < 1.0:
                # At apex, stop
                sandbox.apply_force_to_seat(0, 0)
            else:
                # Apply impulse to adjust vertical motion
                if vy < 0:  # Falling down
                    sandbox.apply_impulse_to_seat(0, 4.2)
                else:  # Rising up
                    sandbox.apply_impulse_to_seat(0, -4.2)
